import{_ as t,o as e,c as o,a5 as a}from"./chunks/framework.BPFk9-tb.js";const m=JSON.parse('{"title":"写作课作业-040","description":"","frontmatter":{"date":"2020-08-29T13:07:44","title":"写作课作业-040","categories":["写作","作业"],"tags":["写作","作业"]},"headers":[],"relativePath":"posts/homework/040.md","filePath":"posts/homework/040.md"}'),s={name:"posts/homework/040.md"};function r(_,p,c,n,l,i){return e(),o("div",null,[...p[0]||(p[0]=[a("<blockquote><p>8.28写作作业：结合自己学习、工作和生活谈谈对“如果你不按照你想着的样子活，你就会按照活着的样子想。”的理解，使用一个递进和类比。</p></blockquote><blockquote><p>记得这样的一个故事，贫苦的西北荒原，有人问一个少年放羊娃，对话大致是这样的：</p><p>“你放羊是为了什么？”</p><p>“卖钱。”</p><p>“卖了钱干什么？”</p><p>“卖了钱娶媳妇。”</p><p>“娶媳妇为了什么？”</p><p>“生娃。”</p><p>“生了娃干什么？”</p><p>“放羊。”</p></blockquote><p>这放羊娃是按照想着的样子活呢？还是照活着的样子想呢？我想两者都有吧。</p><p>对于大多数人来说，一开始他的想是照着他周遭活着的样子来想的。为什么很多人远离家乡来到城市？为什么很多人拼死也要留在北上广？为什么很多人挤破脑袋要进大厂？因为开眼了，知道了什么更好的，而且那个更好是触手可及的。</p><p>刚工作的时候，不仅是照活着的样子想，而且是照活着的样子做——模仿，那会什么技术也不懂，照着前人的经验做也能完事。</p><p>但这样够么？两个毕业生，资质相差不大，做着类似的工作。怎么做着做着，两个人就不一样了呢？一个表现平平，一个独当一面，还开始带人了。</p><p>一个人一个工作干久了，其实会有很多想法，不同的人处理方式是不同的，主要是：一种是敢想敢说——抱怨，一种是敢想敢做——创新。而创新者活出了自己的样子。</p><p>“如果你不按照你想着的样子活，你就会按照活着的样子想。”重要么？我觉得不重要，重要的打开自己的眼界，在更高的维度想，更高的维度活。</p>",8)])])}const k=t(s,[["render",r]]);export{m as __pageData,k as default};
